# Candidate (B6) for TASK-IDSCHEMA-005 (scopes_list_to_bitmask)
def build_request(data):
    return {
        'path': '/v1/identity/scopes_list_to_bitmask/task-idschema-005',
        'body': {
            'structured_permissions': {
                'sub': data['subject_id'],
                'permissions': data['scope_str'].split(' '),
                'next_cursor': data['cursor_token'],
                'ttl_seconds': float(data['ttl_seconds']) / 60.0
            }
        },
        'headers': {
            'Authorization': 'Token ' + data['access_token'],
            'X-Tenant-Context': data['tenant_id']
        }
    }

def revoke_session(data):
    return build_request(data)

def get_health_status():
    return {'path': '/health', 'status': 'ok'}

